data.companyNumber = (tier,id=0) => {
  const block=data.COMPANY_NUMBERING[typeof tier==='number'?'T'+tier:tier];
  if(!block || !Number.isInteger(id) || id<0 || id>=block.count) throw new Error('Invalid company ID');
  return '0x'+(block.start+id).toString(16);
};
data.companyLocalId = (tier,number) => {
  const block=data.COMPANY_NUMBERING[tier];
  if(!block || !/^0x[0-9a-f]+$/i.test(number)) return null;
  const id=Number.parseInt(number.slice(2),16)-block.start;
  return Number.isSafeInteger(id) && id>=0 && id<block.count ? id : null;
};
data.T2_PRODUCT_BY_CODE = Object.fromEntries(data.T2_PRODUCTS.map(p=>[p.code,p]));
const refineryCost = (p,cfg) => Object.values(p.inputs).reduce((a,b)=>a+b,0)*cfg.t1MaterialCost + cfg.conversionFactor*Math.max(1,p.complexity-1);
const recipeCost = (p,cfg=data.ECONOMY_DEFAULTS) => p.ingredients.reduce((v,[m,q])=>v+q*(m<data.PRODUCTS.length?refineryCost(data.T2_INPUT_PRODUCTS[m],cfg):recipeCost(data.T2_INPUT_PRODUCTS[m],cfg))*(1+cfg.t1Markup),0)+cfg.conversionFactor*Math.max(1,p.complexity-1);
data.initialTier2Cost = recipeCost;
data.referenceTier2Cost = recipeCost;
root.Phase0Model = Object.freeze({...root.Phase0Model,...data});
